sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.ec-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  width: 100%;
  padding: 5px 0;
}

.ec-kpi-card {
  background: #ffffff;
  border-radius: 14px;
  padding: 20px;
  min-height: 125px;
  display: flex;
  align-items: center;
  gap: 15px;
  box-shadow: 0 3px 14px rgba(0, 0, 0, 0.08);
  border: 1px solid #e6eeee;
  transition: transform 0.2s ease;
}

.ec-kpi-card:hover {
  transform: translateY(-3px);
}

.ec-kpi-icon {
  width: 50px;
  height: 50px;
  min-width: 50px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

.ec-kpi-icon.complaints {
  background: #e5f5f1;
  color: #087f73;
}

.ec-kpi-icon.risk {
  background: #fff0ed;
  color: #e05a47;
}

.ec-kpi-icon.inspection {
  background: #eaf2ff;
  color: #2563c7;
}

.ec-kpi-icon.completion {
  background: #edf8ee;
  color: #249447;
}

.ec-kpi-title {
  font-size: 14px;
  font-weight: 600;
  color: #667085;
  margin-bottom: 5px;
}

.ec-kpi-value {
  font-size: 30px;
  font-weight: 700;
  line-height: 1.1;
  color: #123b3a;
}

.ec-kpi-subtitle {
  font-size: 11px;
  color: #98a2b3;
  margin-top: 5px;
}

@media (max-width: 900px) {
  .ec-kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 550px) {
  .ec-kpi-grid {
    grid-template-columns: 1fr;
  }
}

sp_widget.script:
(function() {

    // ==============================
    // TOTAL COMPLAINTS
    // ==============================
    var complaintGR = new GlideAggregate('x_snc_environmen_0_complaint');
    complaintGR.addAggregate('COUNT');
    complaintGR.query();

    data.total_complaints = 0;

    if (complaintGR.next()) {
        data.total_complaints = parseInt(
            complaintGR.getAggregate('COUNT'),
            10
        );
    }


    // ==============================
    // HIGH RISK COMPLAINTS
    // ==============================
    var highRiskGR = new GlideAggregate('x_snc_environmen_0_complaint');

    highRiskGR.addQuery('risk_level', 'high');
    highRiskGR.addAggregate('COUNT');
    highRiskGR.query();

    data.high_risk = 0;

    if (highRiskGR.next()) {
        data.high_risk = parseInt(
            highRiskGR.getAggregate('COUNT'),
            10
        );
    }


    // ==============================
    // TOTAL INSPECTIONS
    // ==============================
    var inspectionGR = new GlideAggregate('x_snc_environmen_0_inspection');

    inspectionGR.addAggregate('COUNT');
    inspectionGR.query();

    var totalInspections = 0;

    if (inspectionGR.next()) {
        totalInspections = parseInt(
            inspectionGR.getAggregate('COUNT'),
            10
        );
    }


    // ==============================
    // ACTIVE INSPECTIONS
    // ==============================
    var activeInspectionGR = new GlideAggregate(
        'x_snc_environmen_0_inspection'
    );

    activeInspectionGR.addQuery(
        'inspection_status',
        '!=',
        'completed'
    );

    activeInspectionGR.addAggregate('COUNT');
    activeInspectionGR.query();

    data.active_inspections = 0;

    if (activeInspectionGR.next()) {
        data.active_inspections = parseInt(
            activeInspectionGR.getAggregate('COUNT'),
            10
        );
    }


    // ==============================
    // COMPLETION PERCENTAGE
    // ==============================
    var completedGR = new GlideAggregate(
        'x_snc_environmen_0_inspection'
    );

    completedGR.addQuery(
        'inspection_status',
        'completed'
    );

    completedGR.addAggregate('COUNT');
    completedGR.query();

    var completedInspections = 0;

    if (completedGR.next()) {
        completedInspections = parseInt(
            completedGR.getAggregate('COUNT'),
            10
        );
    }

    if (totalInspections > 0) {
        data.completion_percentage = Math.round(
            (completedInspections / totalInspections) * 100
        );
    } else {
        data.completion_percentage = 0;
    }

})();
